function replaceAll(source: string, replacements: Array<[string, string]>) {
  return replacements.reduce((result, [from, to]) => result.split(from).join(to), source);
}

function alternates(page: Page, canonical: string) {
  return `<link rel="canonical" href="${canonical}">\n  <link rel="alternate" hreflang="en" href="https://villatullia.it${routes.en[page]}">\n  <link rel="alternate" hreflang="de" href="https://villatullia.it${routes.de[page]}">\n  <link rel="alternate" hreflang="it" href="https://villatullia.it${routes.it[page]}">\n  <link rel="alternate" hreflang="nl" href="https://villatullia.it${routes.nl[page]}">\n  <link rel="alternate" hreflang="x-default" href="https://villatullia.it${routes.en[page]}">`;
}

function languageSwitcher(page: Page, locale: PublicLocale) {
  const links = (['en', 'de', 'it', 'nl'] as const).map((language) => `<a href="${routes[language][page]}" lang="${language}" hreflang="${language}"${language === locale ? ' aria-current="page"' : ''}>${language.toUpperCase()}</a>`).join('<span aria-hidden="true">·</span>');
  return `<nav class="language-switcher" aria-label="Language">${links}</nav>`;
}

export function localizedPublicPage(file: 'index.html' | 'calendarw.html' | 'privacy.html', locale: PublicLocale) {
  const page: Page = file === 'index.html' ? 'home' : file === 'calendarw.html' ? 'availability' : 'privacy';
  const source = fs.readFileSync(path.resolve(process.cwd(), file), 'utf8');
  const canonical = `https://villatullia.it${routes[locale][page]}`;
  let html = source
    .replace(/^\s*<link rel="alternate" hreflang="[^"]+" href="[^"]+">\r?\n/gm, '')
    .replace(/<nav class="language-switcher"[^>]*>.*?<\/nav>/, languageSwitcher(page, locale))
    .replace('<html lang="en"', `<html lang="${locale}"`)
    .replace(/<link rel="canonical" href="[^"]+">/, alternates(page, canonical))
    .replace(/<meta property="og:url" content="[^"]+">/, `<meta property="og:url" content="${canonical}">`)
    .replace(/"inLanguage":"en"/g, `"inLanguage":"${locale}"`)
    .replace(/"url":"https:\/\/villatullia\.it\/"/g, `"url":"${canonical}"`)
    .replaceAll('src="imgs/', 'src="/imgs/')
    .replaceAll('href="imgs/', 'href="/imgs/')
    .replaceAll("url('imgs/", "url('/imgs/");
  html = replaceAll(html, [...(page === 'home' ? home[locale] : page === 'availability' ? availability[locale] : privacy[locale]), ...common[locale]]);
  html = html
    .replaceAll('href="calendarw.html#emailEnquiry"', `href="${routes[locale].availability}#emailEnquiry"`)
    .replaceAll('href="calendarw.html"', `href="${routes[locale].availability}"`)
    .replaceAll('href="index.html"', `href="${routes[locale].home}"`)
    .replaceAll('href="privacy.html"', `href="${routes[locale].privacy}"`)
    .replaceAll("link.href.includes('calendarw.html')", `link.href.includes('${routes[locale].availability}')`);
  return html;
}
